"""Week-aware scheduler (WFM-231). Selected per client with `scheduler: week`; the service default stays
`greedy` (wfm/scheduler/greedy.py), so clients without the key are scheduled exactly as before.

Rules enforced while placing (not just audited afterwards):
  - skills; one template per agent per local day; weekly elapsed-hour caps (`weekly_hours`);
    at most `max_consecutive_days` consecutive local days
  - `min_rest_hours`: elapsed time between the end of any shift and the start of the agent's next one
  - `split_contracts`: contracts that may take split templates (e.g. [PT]); `templates`: template ids
    the client uses (default: every template that fits the operating hours)
  - `min_cover` floors on gross cover (an agent counts on the queue they are scheduled on; cross-skilled
    agents count `cross_skill_weight`)
Breaks (`break_placement`): `surplus` puts each break, inside the break window, in the planning interval
where the queue's gross coverage surplus (agents on the queue ignoring breaks minus agents required) is
largest; `midpoint` is greedy.py's rule.

Three passes over the whole week:
  1. greedy placement against the uncovered requirement and floors (gross);
  2. repair: place breaks, then add shifts where coverage net of breaks is short;
  3. prune: drop shifts whose removal leaves no interval short (net) and no floor uncovered.
Deterministic: fixed template order, agent ids as the final tie-break.
"""
from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field
from datetime import date, datetime, timedelta

import pandas as pd

from wfm import constraints
from wfm.ingest.loader import local_days
from wfm.roster import Agent
from wfm.scheduler.greedy import Shift
from wfm.scheduler.templates import Template, eligible, templates_for
from wfm.staffing.required import queue_hours

WASTE_WEIGHT = 0.5   # pass 1: an uncovered interval gained is worth this many intervals of overcover


@dataclass
class _Option:
    day: date
    tpl: Template
    segs: list[tuple[datetime, datetime]]
    ivs: list[int]          # grid indices the segments cover
    hours: float            # elapsed


@dataclass
class _Placed:
    agent: Agent
    queue: str
    opt: _Option
    brk: int | None = None  # grid index of the break interval


@dataclass
class _AgentState:
    shifts: dict[date, _Placed] = field(default_factory=dict)
    hours: float = 0.0


class WeekScheduler:
    def __init__(self, req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str):
        self.cfg = cfg
        self.tz = cfg["tz"]
        self.step = timedelta(minutes=cfg["interval_minutes"])
        self.caps = cfg["weekly_hours"]
        self.max_run = cfg["max_consecutive_days"]
        self.min_rest = timedelta(hours=float(cfg.get("min_rest_hours") or 0))
        self.split_contracts = cfg.get("split_contracts")       # None: as greedy.py (template eligibility)
        rule = cfg["break"]
        self.brk_min_hours = float(rule["min_shift_hours"])
        self.brk_len = timedelta(minutes=rule["minutes"])
        self.brk_window = tuple(timedelta(hours=h) for h in rule["window_hours"])
        self.brk_mode = cfg.get("break_placement", "midpoint")
        self.agents = sorted(agents, key=lambda a: a.agent_id)
        self.queues = list(dict.fromkeys(req["queue"]))

        self.grid: list[datetime] = [pd.Timestamp(t).to_pydatetime() for t in sorted(set(req["interval_start_utc"]))]
        self.idx = {t: i for i, t in enumerate(self.grid)}
        n = len(self.grid)
        self.req = {q: [0] * n for q in self.queues}
        for r in req.itertuples(index=False):
            self.req[r.queue][self.idx[pd.Timestamp(r.interval_start_utc).to_pydatetime()]] = int(r.required)
        self.floor = {q: [constraints.floor(q, t, cfg) for t in self.grid] for q in self.queues}
        self.w = constraints.weight(cfg)
        # operating intervals per queue (attainment): queue_hours, else operating_hours
        self.oper = {q: [self._inside(t, queue_hours(cfg, q)) for t in self.grid] for q in self.queues}

        wanted = cfg.get("templates")
        tpls = [t for t in templates_for(cfg) if wanted is None or t.id in wanted]
        self.options: list[_Option] = []
        for day in local_days(week, self.tz):
            for tpl in tpls:
                segs = tpl.segments_utc(day, self.tz)
                ivs = [self.idx[t] for s, e in segs for t in self.grid if s <= t < e]
                hours = sum((e - s).total_seconds() for s, e in segs) / 3600.0
                if ivs:
                    self.options.append(_Option(day, tpl, segs, ivs, hours))

        self.state = {a.agent_id: _AgentState() for a in self.agents}
        self.placed: list[_Placed] = []
        self.cover = {q: [0] * n for q in self.queues}
        self.cross = {q: [0] * n for q in self.queues}

    def _inside(self, t: datetime, hours) -> bool:
        loc = t.astimezone(self._zone)
        h = loc.hour + loc.minute / 60
        return hours[0] <= h < hours[1]

    @property
    def _zone(self):
        from zoneinfo import ZoneInfo
        return ZoneInfo(self.tz)

    # ---- feasibility -------------------------------------------------------------------------------

    def _can_take(self, a: Agent, q: str, opt: _Option) -> bool:
        st = self.state[a.agent_id]
        if q not in a.skills or opt.day in st.shifts:
            return False
        if opt.tpl.is_split:
            if self.split_contracts is not None and a.contract not in self.split_contracts:
                return False
        if not eligible(opt.tpl, a.contract):
            return False
        if st.hours + opt.hours > self.caps[a.contract] + 1e-9:
            return False
        days = set(st.shifts) | {opt.day}
        run, d = 1, opt.day - timedelta(days=1)
        while d in days:
            run, d = run + 1, d - timedelta(days=1)
        d = opt.day + timedelta(days=1)
        while d in days:
            run, d = run + 1, d + timedelta(days=1)
        if run > self.max_run:
            return False
        start, end = opt.segs[0][0], opt.segs[-1][1]
        for other in st.shifts.values():
            o_start, o_end = other.opt.segs[0][0], other.opt.segs[-1][1]
            if o_start < end and start < o_end:
                return False
            if o_end <= start and start - o_end < self.min_rest:
                return False
            if end <= o_start and o_start - end < self.min_rest:
                return False
        return True

    def _pick(self, q: str, opt: _Option) -> Agent | None:
        cands = [a for a in self.agents if self._can_take(a, q, opt)]
        if not cands:
            return None
        n_q = len(self.queues)
        long_shift = opt.hours >= 8 - 1e-9
        # Keep multi-skilled agents for the queues only they can serve; full-time agents for full days.
        return min(cands, key=lambda a: (len(a.skills & set(self.queues)) if n_q > 1 else 0,
                                         (a.contract != "FT") if long_shift else (a.contract != "PT"),
                                         self.state[a.agent_id].hours / self.caps[a.contract],
                                         a.agent_id))

    # ---- placing and removing ----------------------------------------------------------------------

    def _add(self, a: Agent, q: str, opt: _Option) -> _Placed:
        p = _Placed(a, q, opt)
        st = self.state[a.agent_id]
        st.shifts[opt.day] = p
        st.hours += opt.hours
        self.placed.append(p)
        others = [o for o in self.queues if o != q and o in a.skills]
        for i in opt.ivs:
            self.cover[q][i] += 1
            for o in others:
                self.cross[o][i] += 1
        return p

    def _remove(self, p: _Placed) -> None:
        st = self.state[p.agent.agent_id]
        del st.shifts[p.opt.day]
        st.hours -= p.opt.hours
        self.placed.remove(p)
        others = [o for o in self.queues if o != p.queue and o in p.agent.skills]
        for i in p.opt.ivs:
            self.cover[p.queue][i] -= 1
            for o in others:
                self.cross[o][i] -= 1

    # ---- breaks -------------------------------------------------------------------------------------

    def _break_slots(self, p: _Placed) -> list[int]:
        start = p.opt.segs[0][0]
        lo, hi = start + self.brk_window[0], start + self.brk_window[1]
        out = []
        for i in p.opt.ivs:
            t = self.grid[i]
            if lo <= t <= hi and any(s <= t and t + self.brk_len <= e for s, e in p.opt.segs):
                out.append(i)
        return out

    def place_breaks(self) -> dict[str, list[int]]:
        n = len(self.grid)
        on_break = {q: [0] * n for q in self.queues}
        for p in sorted(self.placed, key=lambda p: (p.opt.segs[0][0], p.agent.agent_id)):
            p.brk = None
            if p.opt.hours < self.brk_min_hours - 1e-9:
                continue
            slots = self._break_slots(p)
            if not slots:
                continue
            q = p.queue
            if self.brk_mode == "surplus":
                start = p.opt.segs[0][0]
                ends = {start + self.brk_window[0], start + self.brk_window[1]}

                def key(i, q=q, ends=ends):
                    gross_surplus = self.cover[q][i] - self.req[q][i]
                    net_after = self.cover[q][i] - on_break[q][i] - 1 - max(self.req[q][i], self.floor[q][i])
                    # largest gross surplus (the rule); among ties: not on a window edge, the most cover
                    # left net of breaks, the earliest
                    return (-gross_surplus, self.grid[i] in ends, -net_after, i)
                p.brk = min(slots, key=key)
            else:
                mid = p.opt.segs[0][0] + timedelta(hours=p.opt.hours / 2)
                p.brk = min(slots, key=lambda i: (abs((self.grid[i] - mid).total_seconds()), i))
            on_break[q][p.brk] += 1
        return on_break

    # ---- shortfalls ---------------------------------------------------------------------------------

    def shortfalls(self, on_break) -> tuple[dict[str, set[int]], dict[str, set[int]]]:
        """(operating intervals short of the requirement net of breaks, intervals below a floor)."""
        short, floor_gap = {}, {}
        for q in self.queues:
            c, b, r, f, x, op = self.cover[q], on_break[q], self.req[q], self.floor[q], self.cross[q], self.oper[q]
            short[q] = {i for i in range(len(self.grid)) if op[i] and c[i] - b[i] < r[i]}
            floor_gap[q] = {i for i in range(len(self.grid)) if c[i] + self.w * x[i] < f[i]}
        return short, floor_gap

    def _badness(self, on_break) -> tuple[int, int]:
        short, gap = self.shortfalls(on_break)
        return sum(map(len, gap.values())), sum(map(len, short.values()))

    # ---- passes -------------------------------------------------------------------------------------

    def pass_greedy(self) -> None:
        dead: set[tuple[int, str]] = set()
        while True:
            best, best_score = None, 0.0
            for k, opt in enumerate(self.options):
                for q in self.queues:
                    if (k, q) in dead:
                        continue
                    gain = sum(min(1.0, constraints.uncovered(self.req[q][i], self.floor[q][i], self.cover[q][i],
                                                              self.cross[q][i], self.cfg)) for i in opt.ivs)
                    if gain < 1.0 - 1e-9:
                        continue
                    score = gain - WASTE_WEIGHT * (len(opt.ivs) - gain)
                    if score > best_score + 1e-9:
                        best, best_score = (k, q, opt), score
            if best is None:
                return
            k, q, opt = best
            a = self._pick(q, opt)
            if a is None:
                dead.add((k, q))
                continue
            self._add(a, q, opt)

    def pass_repair(self) -> None:
        dead: set[tuple[int, str]] = set()
        on_break = self.place_breaks()
        bad = self._badness(on_break)
        while bad != (0, 0):
            short, gap = self.shortfalls(on_break)
            best, best_key = None, None
            for k, opt in enumerate(self.options):
                for q in self.queues:
                    if (k, q) in dead:
                        continue
                    gain = sum(1 for i in opt.ivs if i in short[q] or i in gap[q])
                    if gain == 0:
                        continue
                    key = (-gain, opt.hours, k)
                    if best_key is None or key < best_key:
                        best, best_key = (k, q, opt), key
            if best is None:
                return
            k, q, opt = best
            a = self._pick(q, opt)
            if a is None:
                dead.add((k, q))
                continue
            p = self._add(a, q, opt)
            new_break = self.place_breaks()
            new_bad = self._badness(new_break)
            if new_bad < bad:
                on_break, bad = new_break, new_bad
                dead.clear()
            else:
                self._remove(p)
                dead.add((k, q))
                on_break = self.place_breaks()

    def pass_prune(self) -> None:
        on_break = self.place_breaks()
        bad = self._badness(on_break)
        changed = True
        while changed:
            changed = False
            # longest first, then the shifts with the most overcover
            def waste(p):
                return sum(1 for i in p.opt.ivs if self.cover[p.queue][i] - on_break[p.queue][i] > self.req[p.queue][i])
            for p in sorted(self.placed, key=lambda p: (-p.opt.hours, -waste(p), p.opt.segs[0][0], p.agent.agent_id)):
                self._remove(p)
                new_break = self.place_breaks()
                new_bad = self._badness(new_break)
                if new_bad <= bad:
                    on_break, bad, changed = new_break, new_bad, True
                else:
                    self._add(p.agent, p.queue, p.opt)
                    on_break = self.place_breaks()
        self.place_breaks()

    def run(self) -> list[Shift]:
        self.pass_greedy()
        self.pass_repair()
        self.pass_prune()
        self.place_breaks()
        out = []
        for p in sorted(self.placed, key=lambda p: (p.opt.segs[0][0], p.agent.agent_id)):
            sh = Shift(p.agent.agent_id, p.queue, p.opt.tpl, p.opt.day, list(p.opt.segs),
                       [self.grid[i] for i in p.opt.ivs])
            if p.brk is not None:
                sh.break_start = self.grid[p.brk]
                sh.break_minutes = int(self.brk_len.total_seconds() // 60)
            out.append(sh)
        return out


def schedule_week(req: pd.DataFrame, cfg: dict, agents: list[Agent], week: str) -> list[Shift]:
    return WeekScheduler(req, cfg, agents, week).run()

