s=open(p).read()
old_start = s.index("    def place_breaks(self)")
old_end = s.index("    # ---- shortfalls")
s = s[:old_start] + '''    def _breaks_queue(self, q: str) -> list[int]:
        """Place the breaks of the shifts on `q` (they depend only on `q`'s cover); agents on break per interval."""
        on_break = [0] * len(self.grid)
        cover, req, flo = self.cover[q], self.req[q], self.floor[q]
        for p in sorted((p for p in self.placed if p.queue == q), key=lambda p: (p.opt.segs[0][0], p.agent.agent_id)):
            p.brk = None
            if p.opt.hours < self.brk_min_hours - 1e-9:
                continue
            slots = self._break_slots(p)
            if not slots:
                continue
            if self.brk_mode == "surplus":
                start = p.opt.segs[0][0]
                ends = {start + self.brk_window[0], start + self.brk_window[1]}

                def key(i, ends=ends):
                    gross_surplus = cover[i] - req[i]
                    net_after = cover[i] - on_break[i] - 1 - max(req[i], flo[i])
                    # largest gross surplus (the rule); among ties: not on a window edge, the most cover
                    # left net of breaks, the earliest
                    return (-gross_surplus, self.grid[i] in ends, -net_after, i)
                p.brk = min(slots, key=key)
            else:
                mid = p.opt.segs[0][0] + timedelta(hours=p.opt.hours / 2)
                p.brk = min(slots, key=lambda i: (abs((self.grid[i] - mid).total_seconds()), i))
            on_break[p.brk] += 1
        return on_break

    def place_breaks(self) -> dict[str, list[int]]:
        return {q: self._breaks_queue(q) for q in self.queues}

    def _queue_badness(self, q: str) -> tuple[int, int, int]:
        """(intervals below the floor, operating intervals short net of breaks, total net shortfall) on `q`."""
        b = self._breaks_queue(q)
        c, r, f, x, op = self.cover[q], self.req[q], self.floor[q], self.cross[q], self.oper[q]
        gaps = short = depth = 0
        for i in range(len(self.grid)):
            if c[i] + self.w * x[i] < f[i]:
                gaps += 1
            if op[i] and c[i] - b[i] < r[i]:
                short += 1
                depth += r[i] - (c[i] - b[i])
        return gaps, short, depth

''' + s[old_end:]
s = s.replace('''    def run(self) -> list[Shift]:
        self.pass_greedy()
        self.pass_repair()
        self.pass_prune()''','''    def pass_improve(self, max_rounds: int = 6) -> None:
        """Local search on each queue still short anywhere: move one of its shifts to another template
        or day (same agent) when that leaves the queue less short. Other queues are untouched."""
        hours_cap = self._hours_cap()
        for q in self.queues:
            for _ in range(max_rounds):
                base = self._queue_badness(q)
                if base[:2] == (0, 0):
                    break
                moved = False
                for p in sorted((p for p in self.placed if p.queue == q),
                                key=lambda p: (p.opt.segs[0][0], p.agent.agent_id)):
                    if p not in self.placed:
                        continue
                    self._remove(p)
                    total = self._hours()
                    best, best_val = None, base
                    for opt in self.options:
                        if opt is p.opt or total + opt.hours > hours_cap or not self._can_take(p.agent, q, opt):
                            continue
                        trial = self._add(p.agent, q, opt)
                        val = self._queue_badness(q)
                        self._remove(trial)
                        if val < best_val:
                            best, best_val = opt, val
                    self._add(p.agent, q, best or p.opt)
                    if best is not None:
                        base, moved = best_val, True
                if not moved:
                    break

    def _hours(self) -> float:
        return sum(p.opt.hours for p in self.placed)

    def _hours_cap(self) -> float:
        """Scheduled-hours ceiling from `efficiency_bound` (x required hours), with a 2% margin; none if unset."""
        bound = self.cfg.get("efficiency_bound")
        if not bound:
            return float("inf")
        grain_h = self.step.total_seconds() / 3600
        return 0.98 * bound * grain_h * sum(sum(r) for r in self.req.values())

    def run(self) -> list[Shift]:
        self.pass_greedy()
        self.pass_repair()
        self.pass_prune()
        self.pass_improve()
        self.pass_repair()
        self.pass_prune()''')
open(p,'w').write(s)
